```
http {
    ...
    server {
        listen 199.2.31.2:9938;
        server_name my_user_gfw;
        auth_basic "Restricted Area";
        auth_basic_user_file /etc/nginx/.htpasswd;
        location / {
            root /usr/share/nginx/html;
            index index.html index.htm;
        }
    }
}
```

